import re
from typing import List, Union, Tuple

def tokenize(expr: str) -> List[str]:
    """Tokenize expression into numbers, operators, and parentheses."""
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif expr[i] == '-':
            j = i + 1
            if (j < len(expr) and expr[j].isdigit()) or \
               (i > 0 and expr[i-1] in '()+-*/'):
                j = i + 1
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append('-'.join([expr[i:j]]))
                i = j - 1
            else:
                tokens.append('-')
            i += 1
        elif expr[i] in '+*/()' or (i > 0 and expr[i] == '/'):
            # Handle division by zero later
            tokens.append(expr[i])
            i += 1
        else:
            raise ValueError(f"Invalid character: {expr[i]}")

    return tokens

def evaluate_in_order(tokens: List[str], precedence: dict, right_assoc: bool = False) -> float:
    """Evaluate expression using two-stack algorithm with operator precedence."""
    values = []
    ops = []

    i = 0
    while i < len(tokens):
        token = tokens[i]

        if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            values.append(float(token))
        elif token in '+-*/':
            while (ops and ops[-1] != '(') and \
                   precedence.get(ops[-1], 0) >= precedence[token]:
                if ops[-1] == '*' or ops[-1] == '/':
                    right = values.pop()
                    left = values.pop()
                    op = ops.pop()
                    result = left * right if op == '*' else left / right if op == '/' else None
                    raise ZeroDivisionError("division by zero") if op == '/' and right == 0 else result
                elif op in ['+', '-']:
                    right = values.pop()
                    left = values.pop()
                    result = left + right if op == '+' else left - right if op == '-' else None
                values.append(result)
            ops.append(token)
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                op = ops.pop()
                right = values.pop()
                left = values.pop()
                if op == '*': result = left * right
                elif op == '/': 
                    if right == 0: raise ZeroDivisionError("division by zero")
                    result = left / right
                elif op == '+': result = left + right
                else: result = left - right
                values.append(result)
            ops.pop()  # Pop '('
        i += 1

    while ops:
        op = ops.pop()
        if op == '*': 
            right = values.pop()
            left = values.pop()
            values.append(left * right)
        elif op == '/': 
            right = values.pop()
            left = values.pop()
            if right == 0: raise ZeroDivisionError("division by zero")
            values.append(left / right)
        elif op == '+': 
            right = values.pop()
            left = values.pop()
            values.append(left + right)
        else:
            right = values.pop()
            left = values.pop()
            values.append(left - right)

    if len(values) != 1:
        raise ValueError("Invalid expression")

    return values[0]

def eval_expression(expr: str):
    """Evaluate a mathematical expression string."""
    expr = expr.strip()
    if not expr:
        raise ValueError("Empty expression")

    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2
    }

    return evaluate_in_order(tokenize(expr), precedence)
